consultas_censo.comando:
SELECT COUNT(DISTINCT CO_ENTIDADE) AS total_escolas
FROM matriculas
WHERE QT_MAT_BAS = 0;

SELECT SUM(QT_MAT_BAS_FEM) AS matrículas_feminino, SUM(QT_MAT_BAS_MASC) AS matrículas_masculino, ROUND(100.0 * SUM(QT_MAT_BAS_MASC) / SUM(QT_MAT_BAS_FEM), 2) AS razão
FROM matriculas
WHERE QT_MAT_BAS_FEM > 0 AND QT_MAT_BAS_MASC > 0;
